-- Source: 202610230003_ai_recovery.sql
-- A retry must reuse a completed response, wait for a live request, or report a
-- terminal failure. A failed request ID never starts another billable attempt.
create or replace function public.oqi_ai_begin_request(p_request_id uuid,p_conversation_id uuid,p_message text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare me uuid; conversation uuid:=p_conversation_id; previous public.oqi_ai_requests;
begin
  begin
    me:=public.darsino_account_id();
  exception when sqlstate 'P0001' then
    raise exception using errcode='OQ403',message='AI yordamchidan foydalanish huquqingiz yo‘q.';
  end;
  -- Serialize both the rolling quotas and all new attempts for this account.
  perform 1 from public.darsino_profiles where id=me and role='student' and onboarded for update;
  if not found then
    raise exception using errcode='OQ403',message='AI yordamchi o‘quvchi akkaunti uchun.';
  end if;
  if p_request_id is null or coalesce(char_length(trim(p_message)),0) not between 1 and 2000 then
    raise exception using errcode='OQ400',message='Savol 1–2000 belgidan iborat bo‘lsin.';
  end if;
  select * into previous from public.oqi_ai_requests where id=p_request_id for update;
  if found then
    if previous.user_id<>me then
      raise exception using errcode='OQ403',message='So‘rov identifikatori band.';
    end if;
    if previous.status='completed' then
      return jsonb_build_object('status','completed','conversationId',previous.conversation_id,
        'reply',(select content from public.oqi_ai_messages where request_id=p_request_id and role='assistant'));
    elsif previous.status='failed' then
      return jsonb_build_object('status','failed','conversationId',previous.conversation_id);
    elsif previous.created_at<=now()-interval '60 seconds' then
      update public.oqi_ai_requests set status='failed',completed_at=now() where id=previous.id;
      return jsonb_build_object('status','expired','conversationId',previous.conversation_id);
    end if;
    return jsonb_build_object('status','pending','conversationId',previous.conversation_id);
  end if;
  update public.oqi_ai_requests set status='failed',completed_at=now()
    where user_id=me and status='pending' and created_at<=now()-interval '60 seconds';
  if exists(select 1 from public.oqi_ai_requests where user_id=me and status='pending') then
    raise exception using errcode='OQ429',message='Avvalgi javobni kuting.';
  end if;
  if (select count(*) from public.oqi_ai_requests where user_id=me and created_at>now()-interval '1 minute')>=5 then
    raise exception using errcode='OQ429',message='Bir daqiqada 5 ta savol mumkin. Biroz kuting.';
  end if;
  if (select count(*) from public.oqi_ai_requests where user_id=me and created_at>now()-interval '24 hours')>=30 then
    raise exception using errcode='OQ429',message='24 soatlik 30 ta savol limiti tugadi.';
  end if;
  if conversation is null then
    insert into public.oqi_ai_conversations(user_id) values(me) returning id into conversation;
  elsif not exists(select 1 from public.oqi_ai_conversations where id=conversation and user_id=me) then
    raise exception using errcode='OQ403',message='Suhbat topilmadi.';
  end if;
  insert into public.oqi_ai_requests(id,user_id,conversation_id) values(p_request_id,me,conversation);
  insert into public.oqi_ai_messages(conversation_id,request_id,role,content) values(conversation,p_request_id,'user',trim(p_message));
  return jsonb_build_object('status','reserved','conversationId',conversation,'messages',coalesce((select jsonb_agg(jsonb_build_object('role',m.role,'content',m.content) order by m.id) from (
    select m.* from public.oqi_ai_messages m join public.oqi_ai_requests r on r.id=m.request_id
    where m.conversation_id=conversation and (r.status='completed' or r.id=p_request_id) order by m.id desc limit 15
  ) m),'[]'::jsonb));
end $$;

revoke all on function public.oqi_ai_begin_request(uuid,uuid,text) from public,anon,authenticated;
grant execute on function public.oqi_ai_begin_request(uuid,uuid,text) to authenticated;

-- Source: 202610230004_storage_limits.sql
-- Storage can populate object metadata after reserving an upload. Charge the
-- bucket's maximum before accepting bytes instead of trusting the client's size
-- or depending on metadata being available in the Storage INSERT policy.
alter table public.darsino_files add column if not exists reserved_size_bytes bigint;
update public.darsino_files f set reserved_size_bytes=
  case when f.state in ('pending','deleting') then
    greatest(f.size_bytes,coalesce((select b.file_size_limit from storage.buckets b where b.id=f.bucket_id),f.size_bytes))
  else f.size_bytes end
where f.reserved_size_bytes is null;
alter table public.darsino_files alter column reserved_size_bytes set not null;
do $$ begin
  if not exists(select 1 from pg_constraint where conrelid='public.darsino_files'::regclass and conname='darsino_files_reserved_size_valid') then
    alter table public.darsino_files add constraint darsino_files_reserved_size_valid check(reserved_size_bytes>=size_bytes);
  end if;
end $$;

create or replace function public.darsino_prepare_upload(
  p_purpose text,p_original_name text,p_mime_type text,p_size_bytes bigint,
  p_conversation_id text default null,p_offering_id uuid default null
) returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  me uuid:=public.darsino_account_id(); f public.darsino_files; bucket text; lim bigint; ext text;
  mime text:=lower(trim(p_mime_type));
begin
  -- Serialize allocation with other upload reservations for this account.
  perform 1 from public.darsino_profiles where id=me for update;
  perform public.darsino_assert(p_purpose in ('avatar','verification','chat','material','cover'),'Fayl maqsadi noto‘g‘ri.');
  perform public.darsino_assert(char_length(trim(p_original_name)) between 1 and 180 and p_original_name !~ '[[:cntrl:]/\\]','Fayl nomi noto‘g‘ri.');
  bucket:=case p_purpose when 'avatar' then 'darsino-avatars' when 'verification' then 'darsino-verifications'
    when 'chat' then 'darsino-chat-files' when 'material' then 'darsino-lesson-materials' when 'cover' then 'darsino-group-covers' end;
  select file_size_limit into lim from storage.buckets where id=bucket and mime=any(allowed_mime_types);
  perform public.darsino_assert(lim is not null and p_size_bytes between 1 and lim,'Fayl turi yoki hajmi ruxsat etilmagan.');
  perform public.darsino_assert((p_purpose='chat')=(p_conversation_id is not null) and (p_purpose in ('material','cover'))=(p_offering_id is not null),'Fayl bog‘lanishi noto‘g‘ri.');
  if p_purpose='verification' then
    perform public.darsino_assert(exists(select 1 from public.darsino_tutors where user_id=me),'Repetitor profilini to‘ldiring.');
  elsif p_purpose='chat' then
    perform public.darsino_assert(public.darsino_can_message(p_conversation_id),'Suhbatga yozish huquqi yo‘q.');
  elsif p_purpose in ('material','cover') then
    perform public.darsino_assert(exists(select 1 from public.darsino_offerings o join public.darsino_tutors t on t.user_id=o.tutor_id where o.id=p_offering_id and o.tutor_id=me and t.verification='approved'),'Faqat tasdiqlangan dars egasi fayl yuklaydi.');
  end if;
  perform public.darsino_assert((select count(*) from public.darsino_files where owner_id=me and state='pending' and created_at>now()-interval '1 hour')<20,'Yuklanayotgan fayllar soni ko‘p. Avval ularni yakunlang.');
  perform public.darsino_assert((select count(*) from public.darsino_files where owner_id=me and state<>'deleted')<1000
    and (select coalesce(sum(reserved_size_bytes),0) from public.darsino_files where owner_id=me and state<>'deleted')+lim<=2147483648,'Akkaunt fayl limiti tugadi.');
  ext:=case mime when 'image/jpeg' then 'jpg' when 'image/png' then 'png' when 'image/webp' then 'webp' when 'application/pdf' then 'pdf' when 'video/mp4' then 'mp4' when 'video/webm' then 'webm'
    when 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' then 'docx'
    when 'application/vnd.openxmlformats-officedocument.presentationml.presentation' then 'pptx'
    when 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' then 'xlsx' end;
  f.id:=gen_random_uuid();
  insert into public.darsino_files(id,owner_id,purpose,bucket_id,object_path,original_name,mime_type,size_bytes,reserved_size_bytes,conversation_id,offering_id)
    values(f.id,me,p_purpose,bucket,me::text||'/'||f.id::text||'.'||ext,trim(p_original_name),mime,p_size_bytes,lim,p_conversation_id,p_offering_id) returning * into f;
  return public.darsino_file_json(f);
end $$;

create or replace function public.darsino_finalize_upload(p_file_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare me uuid:=public.darsino_account_id(); f public.darsino_files; meta jsonb;
begin
  select * into f from public.darsino_files where id=p_file_id and owner_id=me for update;
  perform public.darsino_assert(found and f.state in ('pending','ready'),'Yuklash topilmadi yoki o‘chirish boshlangan.');
  select metadata into meta from storage.objects where bucket_id=f.bucket_id and name=f.object_path;
  perform public.darsino_assert(found and (meta->>'size')::bigint=f.size_bytes and lower(meta->>'mimetype')=f.mime_type,'Storage fayli, MIME turi yoki haqiqiy hajmi mos emas.');
  -- Release unused capacity only after the stored object has passed validation.
  -- Deletion keeps this persisted charge until forget_file marks it deleted.
  update public.darsino_files set state='ready',reserved_size_bytes=f.size_bytes,updated_at=now() where id=f.id returning * into f;
  return public.darsino_file_json(f);
end $$;

comment on column public.darsino_files.reserved_size_bytes is 'Account quota charge: bucket maximum until Storage metadata is verified, then actual size; retained while deleting and excluded only when deleted.';

-- Source: 202610230005_api_reliability.sql
-- One command key represents one user intent, even if its HTTP response is lost.
-- Receipts retain a fixed-size SHA-256 intent digest, no message bodies or JWTs;
-- replies use current scoped state. Fresh keys have per-account write budgets.

create table if not exists public.darsino_mutation_receipts (
  actor_id uuid not null references public.darsino_profiles(id) on delete cascade,
  idempotency_key uuid not null,
  command_hash bytea not null check (octet_length(command_hash)=32),
  result_id uuid,
  created_at timestamptz not null default now(),
  primary key(actor_id,idempotency_key)
);
create index if not exists darsino_mutation_receipts_created on public.darsino_mutation_receipts(created_at);
alter table public.darsino_mutation_receipts enable row level security;
revoke all on public.darsino_mutation_receipts from public,anon,authenticated;

-- A single notification is generated for text and file messages alike.
alter table public.darsino_notifications add column if not exists message_id uuid references public.darsino_messages(id) on delete cascade;
create unique index if not exists darsino_notifications_message on public.darsino_notifications(message_id) where message_id is not null;
create index if not exists darsino_messages_recipient_time on public.darsino_messages(recipient_id,created_at desc,id);
create index if not exists darsino_messages_conversation_time on public.darsino_messages(conversation_id,created_at desc,id);
create index if not exists darsino_notifications_unread on public.darsino_notifications(user_id,created_at desc) where not read;

create or replace function public.darsino_notify_new_message(p_message_id uuid) returns void
language sql security definer set search_path='' as $$
  insert into public.darsino_notifications(user_id,title,body,message_id)
  select m.recipient_id,'Yangi xabar',left(m.text,140),m.id
  from public.darsino_messages m where m.id=p_message_id
  on conflict(message_id) where message_id is not null do nothing
$$;
create or replace function public.darsino_message_notification() returns trigger
language plpgsql security definer set search_path='' as $$
begin
  perform public.darsino_notify_new_message(new.id);
  return new;
end $$;
revoke all on function public.darsino_notify_new_message(uuid),public.darsino_message_notification() from public,anon,authenticated;
drop trigger if exists darsino_message_notification on public.darsino_messages;
create trigger darsino_message_notification after insert on public.darsino_messages
for each row execute function public.darsino_message_notification();

do $$ begin
  if to_regprocedure('public.darsino_mutate_idempotent_base(jsonb)') is null then
    alter function public.darsino_mutate(jsonb) rename to darsino_mutate_idempotent_base;
  end if;
end $$;
create or replace function public.darsino_mutate(command jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare
  me uuid:=public.darsino_account_id(); key uuid; intent jsonb; intent_hash bytea; result jsonb;
  receipt public.darsino_mutation_receipts;
begin
  perform public.darsino_assert(jsonb_typeof(command)='object','So‘rov formati noto‘g‘ri.');
  perform public.darsino_assert(command->>'actorId'=me::text,'Akkaunt o‘zgardi. Amalni qayta boshlang.');
  perform public.darsino_assert(octet_length(command::text)<=65536,'So‘rov juda katta.');
  -- Existing clients remain usable; upgraded clients supply a UUID per intent.
  if not command ? 'idempotencyKey' then
    return public.darsino_mutate_idempotent_base(command);
  end if;
  perform public.darsino_assert(jsonb_typeof(command->'idempotencyKey')='string' and
    command->>'idempotencyKey' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$',
    'So‘rov identifikatori noto‘g‘ri.');
  key:=(command->>'idempotencyKey')::uuid;
  intent:=command-'idempotencyKey';
  intent_hash:=sha256(convert_to(intent::text,'UTF8'));
  -- The lock serializes matching keys across independent API workers. It is
  -- acquired before authority/scheduling row locks in the delegated command.
  perform pg_advisory_xact_lock(hashtextextended('oqi.command:'||me::text||':'||key::text,0));
  select * into receipt from public.darsino_mutation_receipts
    where actor_id=me and idempotency_key=key;
  if found then
    if receipt.command_hash<>intent_hash then
      raise exception 'So‘rov identifikatori boshqa amal uchun ishlatilgan.' using errcode='22023';
    end if;
    return public.darsino_snapshot()||jsonb_build_object('id',receipt.result_id);
  end if;
  -- Replays are free; only a genuinely new, successfully committed intent
  -- consumes budget. A failed transaction rolls these counters back as well.
  perform public.darsino_account_rate('mutation-minute',120,60);
  perform public.darsino_account_rate('mutation-day',1000,86400);
  result:=public.darsino_mutate_idempotent_base(intent);
  insert into public.darsino_mutation_receipts(actor_id,idempotency_key,command_hash,result_id)
    values(me,key,intent_hash,nullif(result->>'id','')::uuid);
  return result;
end $$;
revoke all on function public.darsino_mutate_idempotent_base(jsonb) from public,anon,authenticated;
revoke all on function public.darsino_mutate(jsonb) from public,anon;
grant execute on function public.darsino_mutate(jsonb) to authenticated;

-- Service/admin maintenance only. Never expire a key in its first 24 hours.
create or replace function public.darsino_prune_mutation_receipts(p_before timestamptz default now()-interval '30 days') returns bigint
language plpgsql security definer set search_path='' as $$
declare removed bigint;
begin
  perform public.darsino_assert(p_before is not null and p_before<=now()-interval '24 hours','Oxirgi 24 soatdagi so‘rovlar saqlanishi kerak.');
  delete from public.darsino_mutation_receipts where created_at<p_before;
  get diagnostics removed=row_count;
  return removed;
end $$;
revoke all on function public.darsino_prune_mutation_receipts(timestamptz) from public,anon,authenticated;
grant execute on function public.darsino_prune_mutation_receipts(timestamptz) to service_role;
notify pgrst,'reload schema';

-- Source: 202610230006_storage_lifecycle.sql
-- Keep the reservation alive through the Storage INSERT transaction. Otherwise
-- deletion could observe no committed object, release its quota, and then leave
-- an object orphaned when an already-authorized upload commits afterward.
create or replace function public.darsino_storage_insert(bucket text,path text) returns boolean
language plpgsql volatile security definer set search_path='' as $$
declare f public.darsino_files;
begin
  if not public.darsino_authenticated() then return false; end if;
  -- Filter ownership before acquiring a lock: guessing another account's object
  -- path must not let an unauthorized caller block its upload or deletion.
  select * into f from public.darsino_files
    where bucket_id=bucket and object_path=path and owner_id=auth.uid()
    for share;
  if not found then return false; end if;
  -- Check the locked row, including any state change committed while waiting.
  -- Storage may write authoritative object metadata later in its upload flow.
  return f.state='pending' and f.created_at>now()-interval '1 hour';
end $$;

revoke all on function public.darsino_storage_insert(text,text) from public,anon,authenticated;
grant execute on function public.darsino_storage_insert(text,text) to anon,authenticated;
comment on function public.darsino_storage_insert(text,text) is 'Storage INSERT authorization holds a shared reservation-row lock until upload transaction end, serializing deletion and quota release without depending on early object metadata.';

-- Source: 202610260001_teacher_workspace.sql
-- Group conversations and tutor-created mock tests. Existing marketplace data is retained.

create table if not exists public.oqi_group_messages (
  id uuid primary key, offering_id uuid not null references public.darsino_offerings(id),
  sender_id uuid not null references public.darsino_profiles(id),
  text text not null check(char_length(text) between 1 and 2000),
  announcement boolean not null default false, created_at timestamptz not null default now()
);
create index if not exists oqi_group_messages_page on public.oqi_group_messages(offering_id,created_at desc,id desc);
create table if not exists public.oqi_group_reads (
  offering_id uuid not null references public.darsino_offerings(id),
  user_id uuid not null references public.darsino_profiles(id),
  read_until timestamptz not null default '-infinity', primary key(offering_id,user_id)
);
create table if not exists public.oqi_mock_tests (
  id uuid primary key, tutor_id uuid not null references public.darsino_profiles(id),
  offering_id uuid not null references public.darsino_offerings(id),
  title text not null check(char_length(title) between 3 and 150), subject text not null,
  source text not null check(source in ('file','manual','catalog')),
  file_id uuid unique references public.darsino_files(id),
  question_count integer not null check(question_count between 1 and 50),
  minutes integer not null check(minutes between 5 and 240),
  difficulty text not null check(difficulty in ('easy','medium','advanced')),
  scoring text not null check(scoring in ('uniform','dtm')),
  questions jsonb not null default '[]', answer_key jsonb not null,
  status text not null default 'draft' check(status in ('draft','published')),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index if not exists oqi_mock_tests_group on public.oqi_mock_tests(offering_id,status,created_at desc);
create table if not exists public.oqi_mock_attempts (
  id uuid primary key default gen_random_uuid(), test_id uuid not null references public.oqi_mock_tests(id),
  student_id uuid not null references public.darsino_profiles(id), started_at timestamptz not null default now(),
  answers jsonb, correct_count integer, score numeric, max_score numeric, percentage integer,
  completed_at timestamptz, unique(test_id,student_id)
);
create index if not exists oqi_mock_attempts_student on public.oqi_mock_attempts(student_id,completed_at desc);

do $$ declare n text; begin
  foreach n in array array['oqi_group_messages','oqi_group_reads','oqi_mock_tests','oqi_mock_attempts'] loop
    execute format('alter table public.%I enable row level security',n);
    execute format('revoke all on table public.%I from public,anon,authenticated',n);
  end loop;
end $$;

create or replace function public.oqi_classroom_access(p_group uuid) returns boolean
language sql stable security definer set search_path='' as $$
  select public.darsino_authenticated() and exists(
    select 1 from public.darsino_offerings o join public.darsino_profiles p on p.id=o.tutor_id
    where o.id=p_group and not p.is_suspended and (o.tutor_id=auth.uid() or (
      exists(select 1 from public.darsino_tutors t where t.user_id=o.tutor_id and t.verification='approved')
      and not public.darsino_blocked(auth.uid(),o.tutor_id)
      and exists(select 1 from public.darsino_enrollments e where e.offering_id=o.id and e.student_id=auth.uid() and e.active))))
$$;
create or replace function public.oqi_group_message_json(m public.oqi_group_messages) returns jsonb
language sql stable security definer set search_path='' as $$
  select jsonb_build_object('id',m.id,'offeringId',m.offering_id,'senderId',m.sender_id,
    'senderName',(select name from public.darsino_profiles where id=m.sender_id),
    'text',m.text,'announcement',m.announcement,'createdAt',m.created_at)
$$;
create or replace function public.oqi_mock_test_json(t public.oqi_mock_tests) returns jsonb
language sql stable security definer set search_path='' as $$
  select jsonb_build_object('id',t.id,'tutorId',t.tutor_id,'offeringId',t.offering_id,'title',t.title,
    'subject',t.subject,'source',t.source,'fileId',t.file_id,'questionCount',t.question_count,
    'minutes',t.minutes,'difficulty',t.difficulty,'scoring',t.scoring,'questions',t.questions,
    'status',t.status,'createdAt',t.created_at,'updatedAt',t.updated_at)
    ||case when t.tutor_id=auth.uid() then jsonb_build_object('answerKey',t.answer_key) else '{}'::jsonb end
$$;
create or replace function public.oqi_mock_attempt_json(a public.oqi_mock_attempts) returns jsonb
language sql stable security definer set search_path='' as $$
  select jsonb_build_object('id',a.id,'testId',a.test_id,'studentId',a.student_id,
    'startedAt',a.started_at,'answers',a.answers,'correctCount',a.correct_count,'score',a.score,
    'maxScore',a.max_score,'percentage',a.percentage,'completedAt',a.completed_at)
$$;

create or replace function public.oqi_classroom_snapshot() returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare me uuid:=public.darsino_account_id(); result jsonb;
begin
  select jsonb_build_object(
    'groups',coalesce((select jsonb_agg(jsonb_build_object('id',o.id,'title',o.data->>'title',
      'subject',o.data->>'subject','tutorId',o.tutor_id,
      'memberCount',(select count(*) from public.darsino_enrollments e where e.offering_id=o.id and e.active),
      'lastMessage',(select public.oqi_group_message_json(m) from public.oqi_group_messages m where m.offering_id=o.id order by m.created_at desc,m.id desc limit 1),
      'announcement',(select public.oqi_group_message_json(m) from public.oqi_group_messages m where m.offering_id=o.id and m.announcement order by m.created_at desc,m.id desc limit 1),
      'unread',(select count(*) from public.oqi_group_messages m where m.offering_id=o.id and m.sender_id<>me and m.created_at>coalesce((select r.read_until from public.oqi_group_reads r where r.offering_id=o.id and r.user_id=me),'-infinity'))
    ) order by o.id) from public.darsino_offerings o where o.data->>'type'='group' and public.oqi_classroom_access(o.id)),'[]'::jsonb),
    'tests',coalesce((select jsonb_agg(public.oqi_mock_test_json(t) order by t.created_at desc) from public.oqi_mock_tests t
      where t.tutor_id=me or (t.status='published' and public.oqi_classroom_access(t.offering_id))),'[]'::jsonb),
    'attempts',coalesce((select jsonb_agg(public.oqi_mock_attempt_json(a) order by a.started_at desc) from public.oqi_mock_attempts a
      join public.oqi_mock_tests t on t.id=a.test_id where t.tutor_id=me or (a.student_id=me and public.oqi_classroom_access(t.offering_id))),'[]'::jsonb)
  ) into result;
  return result;
end $$;

create or replace function public.oqi_group_messages_read(p_group uuid,p_before uuid default null,p_limit integer default 50) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare me uuid:=public.darsino_account_id(); boundary public.oqi_group_messages; result jsonb;
begin
  perform public.darsino_assert(public.oqi_classroom_access(p_group),'Bu guruh suhbatiga ruxsat yo‘q.');
  if p_before is not null then
    select * into boundary from public.oqi_group_messages where id=p_before and offering_id=p_group;
    perform public.darsino_assert(found,'Xabar sahifasi topilmadi.');
  end if;
  select coalesce(jsonb_agg(public.oqi_group_message_json(m) order by m.created_at,m.id),'[]'::jsonb) into result from (
    select m.* from public.oqi_group_messages m where m.offering_id=p_group
      and (p_before is null or (m.created_at,m.id)<(boundary.created_at,boundary.id))
    order by m.created_at desc,m.id desc limit greatest(1,least(coalesce(p_limit,50),100))) m;
  return result;
end $$;
create or replace function public.oqi_group_message_send(p_group uuid,p_id uuid,p_text text,p_announcement boolean default false) returns jsonb
language plpgsql security definer set search_path='' as $$
declare me uuid:=public.darsino_account_id(); message public.oqi_group_messages; clean text:=trim(p_text);
begin
  perform public.darsino_assert(public.oqi_classroom_access(p_group),'Bu guruh suhbatiga ruxsat yo‘q.');
  perform public.darsino_assert(p_id is not null and char_length(clean) between 1 and 2000,'Xabar 1–2000 belgi bo‘lsin.');
  perform public.darsino_assert(exists(select 1 from public.darsino_profiles where id=me and onboarded),'Avval profilingizni to‘ldiring.');
  perform public.darsino_assert(not exists(select 1 from public.darsino_offerings where id=p_group and tutor_id=me) or exists(select 1 from public.darsino_tutors where user_id=me and verification='approved'),'Tasdiqlangan ustoz profili kerak.');
  perform public.darsino_assert(not p_announcement or exists(select 1 from public.darsino_offerings where id=p_group and tutor_id=me),'E’lonni faqat guruh ustozi yuboradi.');
  perform 1 from public.darsino_profiles where id=me for no key update;
  perform pg_advisory_xact_lock(hashtextextended('oqi-group-message:'||p_id::text,0));
  select * into message from public.oqi_group_messages where id=p_id;
  if found then
    perform public.darsino_assert(message.sender_id=me and message.offering_id=p_group and message.text=clean and message.announcement=p_announcement,'Xabar kaliti boshqa amal uchun ishlatilgan.');
    return public.oqi_group_message_json(message);
  end if;
  perform public.darsino_account_rate('message',60,60);
  insert into public.oqi_group_messages(id,offering_id,sender_id,text,announcement)
    values(p_id,p_group,me,clean,p_announcement) returning * into message;
  return public.oqi_group_message_json(message);
end $$;
create or replace function public.oqi_group_mark_read(p_group uuid,p_until timestamptz) returns void
language plpgsql security definer set search_path='' as $$
declare me uuid:=public.darsino_account_id();
begin
  perform public.darsino_assert(public.oqi_classroom_access(p_group),'Bu guruh suhbatiga ruxsat yo‘q.');
  perform public.darsino_assert(p_until is not null,'O‘qilgan xabar vaqti kerak.');
  insert into public.oqi_group_reads(offering_id,user_id,read_until) values(p_group,me,least(now(),p_until))
    on conflict(offering_id,user_id) do update set read_until=greatest(oqi_group_reads.read_until,excluded.read_until);
end $$;

create or replace function public.oqi_mock_test_save(p_test jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare me uuid:=public.darsino_account_id(); old public.oqi_mock_tests; saved public.oqi_mock_tests;
  group_id uuid:=(p_test->>'offeringId')::uuid; test_id uuid:=(p_test->>'id')::uuid;
  file uuid:=nullif(p_test->>'fileId','')::uuid; n integer:=(p_test->>'questionCount')::integer;
  mins integer:=(p_test->>'minutes')::integer; state text:=p_test->>'status';
  source_kind text:=p_test->>'source'; questions jsonb:=coalesce(p_test->'questions','[]'); keys jsonb:=p_test->'answerKey';
  item jsonb; i integer; was_published boolean:=false;
begin
  perform public.darsino_assert(jsonb_typeof(p_test)='object' and octet_length(p_test::text)<=180000,'Test ma’lumoti juda katta.');
  perform public.darsino_assert(exists(select 1 from public.darsino_offerings o join public.darsino_tutors t on t.user_id=o.tutor_id where o.id=group_id and o.tutor_id=me and t.verification='approved'),'O‘z guruhingiz va tasdiqlangan ustoz profili kerak.');
  perform public.darsino_assert(test_id is not null and char_length(trim(p_test->>'title')) between 3 and 150,'Test nomini kiriting.');
  perform public.darsino_assert(n between 1 and 50 and mins between 5 and 240,'Savollar soni 1–50, vaqt 5–240 daqiqa bo‘lsin.');
  perform public.darsino_assert(state in ('draft','published') and source_kind in ('file','manual','catalog') and p_test->>'difficulty' in ('easy','medium','advanced'),'Test parametrlari noto‘g‘ri.');
  perform public.darsino_assert(p_test->>'scoring' in ('uniform','dtm') and (p_test->>'scoring'<>'dtm' or n=30),'DTM ball tizimi 30 savol uchun.');
  perform public.darsino_assert(exists(select 1 from public.darsino_tutors where user_id=me and data->'subjects' ? (p_test->>'subject')),'Profilingizdagi fanni tanlang.');
  perform public.darsino_assert(jsonb_typeof(keys)='array' and jsonb_array_length(keys)=n,'Har bir savolning javob kalitini kiriting.');
  for item in select * from jsonb_array_elements(keys) loop
    perform public.darsino_assert(item='null'::jsonb and state='draft' or (jsonb_typeof(item)='number' and item::text ~ '^[0-3]$'),'Javoblar A–D oralig‘ida bo‘lsin.');
  end loop;
  if source_kind<>'file' then
    perform public.darsino_assert(jsonb_typeof(questions)='array' and jsonb_array_length(questions)=n,'Savollar matnini kiriting.');
    for item in select * from jsonb_array_elements(questions) loop
      perform public.darsino_assert(jsonb_typeof(item)='object' and char_length(trim(item->>'prompt')) between 1 and 2000 and jsonb_typeof(item->'options')='array' and jsonb_array_length(item->'options')=4,'Savol va to‘rtta javob variantini kiriting.');
      perform public.darsino_assert(not exists(select 1 from jsonb_array_elements(item->'options') v where jsonb_typeof(v)<>'string' or char_length(trim(v#>>'{}')) not between 1 and 500),'Javob variantlari bo‘sh bo‘lmasin.');
    end loop;
    -- A client cannot smuggle a correct answer into student-visible question JSON.
    select jsonb_agg(jsonb_build_object('prompt',q->'prompt','options',q->'options')) into questions from jsonb_array_elements(questions) q;
  else
    questions:='[]';
    perform public.darsino_assert(state='draft' or file is not null,'Savollar faylini yuklang.');
  end if;
  if file is not null then
    perform public.darsino_assert(exists(select 1 from public.darsino_files f where f.id=file and f.owner_id=me and f.purpose='material' and f.offering_id=group_id and f.state='ready' and f.mime_type in ('application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document')),'Shu guruh uchun tayyor PDF yoki DOCX fayl kerak.');
  end if;
  perform 1 from public.darsino_profiles where id=me for no key update;
  perform pg_advisory_xact_lock(hashtextextended('oqi-mock-test:'||test_id::text,0));
  select * into old from public.oqi_mock_tests where id=test_id for update;
  if found then
    perform public.darsino_assert(old.tutor_id=me and old.offering_id=group_id,'Boshqa ustoz testini o‘zgartirib bo‘lmaydi.');
    was_published:=old.status='published';
    if exists(select 1 from public.oqi_mock_attempts a where a.test_id=old.id) then
      perform public.darsino_assert((old.title,old.subject,old.source,old.file_id,old.question_count,old.minutes,old.difficulty,old.scoring,old.questions,old.answer_key,old.status)
        is not distinct from (trim(p_test->>'title'),p_test->>'subject',source_kind,file,n,mins,p_test->>'difficulty',p_test->>'scoring',questions,keys,state),'Ishlash boshlangan testni o‘zgartirib bo‘lmaydi.');
      return public.oqi_mock_test_json(old);
    end if;
  end if;
  perform public.darsino_account_rate('mock-test-save',60,60);
  insert into public.oqi_mock_tests(id,tutor_id,offering_id,title,subject,source,file_id,question_count,minutes,difficulty,scoring,questions,answer_key,status)
    values(test_id,me,group_id,trim(p_test->>'title'),p_test->>'subject',source_kind,file,n,mins,p_test->>'difficulty',p_test->>'scoring',questions,keys,state)
    on conflict(id) do update set title=excluded.title,subject=excluded.subject,source=excluded.source,file_id=excluded.file_id,
      question_count=excluded.question_count,minutes=excluded.minutes,difficulty=excluded.difficulty,scoring=excluded.scoring,
      questions=excluded.questions,answer_key=excluded.answer_key,status=excluded.status,updated_at=now()
    returning * into saved;
  if old.file_id is not null and (old.file_id is distinct from file or state='draft') then
    update public.darsino_lesson_files set published=false where file_id=old.file_id;
  end if;
  if file is not null and state='published' then
    insert into public.darsino_lesson_files(offering_id,file_id,title,published) values(group_id,file,saved.title,true)
      on conflict(file_id) do update set title=excluded.title,published=true;
  end if;
  if state='published' and not was_published then
    insert into public.darsino_notifications(user_id,title,body,offering_id)
      select e.student_id,'Yangi mock test',saved.title,group_id from public.darsino_enrollments e where e.offering_id=group_id and e.active;
  end if;
  return public.oqi_mock_test_json(saved);
end $$;

create or replace function public.oqi_mock_begin(p_test uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare me uuid:=public.darsino_account_id(); t public.oqi_mock_tests; a public.oqi_mock_attempts;
begin
  select * into t from public.oqi_mock_tests where id=p_test for share;
  perform public.darsino_assert(found and t.status='published' and public.oqi_classroom_access(t.offering_id) and exists(select 1 from public.darsino_profiles where id=me and role='student' and onboarded),'Bu testni ishlashga ruxsat yo‘q.');
  perform public.darsino_account_rate('mock-begin',30,60);
  insert into public.oqi_mock_attempts(test_id,student_id) values(t.id,me) on conflict(test_id,student_id) do nothing;
  select * into a from public.oqi_mock_attempts where test_id=t.id and student_id=me;
  return public.oqi_mock_attempt_json(a);
end $$;
create or replace function public.oqi_mock_submit(p_test uuid,p_answers jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare me uuid:=public.darsino_account_id(); t public.oqi_mock_tests; a public.oqi_mock_attempts;
  i integer; correct integer:=0; points numeric:=0; maximum numeric:=0; weight numeric; answer jsonb;
begin
  select * into t from public.oqi_mock_tests where id=p_test for share;
  perform public.darsino_assert(found and t.status='published' and public.oqi_classroom_access(t.offering_id),'Bu testga ruxsat yo‘q.');
  select * into a from public.oqi_mock_attempts where test_id=p_test and student_id=me for update;
  perform public.darsino_assert(found,'Avval testni boshlang.');
  if a.completed_at is not null then
    perform public.darsino_assert(a.answers=p_answers,'Natija saqlangan. Javoblarni qayta o‘zgartirib bo‘lmaydi.');
    return public.oqi_mock_attempt_json(a);
  end if;
  perform public.darsino_assert(now()<=a.started_at+make_interval(mins=>t.minutes)+interval '20 seconds','Test vaqti yakunlandi.');
  perform public.darsino_assert(jsonb_typeof(p_answers)='array' and jsonb_array_length(p_answers)=t.question_count,'Javoblar soni testga mos bo‘lsin.');
  for i in 0..t.question_count-1 loop
    answer:=p_answers->i;
    perform public.darsino_assert(answer='null'::jsonb or (jsonb_typeof(answer)='number' and answer::text ~ '^[0-3]$'),'Javoblar A–D oralig‘ida bo‘lsin.');
    weight:=case when t.scoring='dtm' then case when i<10 then 1.1 when i<20 then 2.1 else 3.1 end else 1 end;
    maximum:=maximum+weight;
    if answer<>'null'::jsonb and answer=t.answer_key->i then correct:=correct+1; points:=points+weight; end if;
  end loop;
  update public.oqi_mock_attempts set answers=p_answers,correct_count=correct,score=points,max_score=maximum,
    percentage=round(100*points/maximum),completed_at=now() where id=a.id returning * into a;
  insert into public.darsino_notifications(user_id,title,body,offering_id) values(t.tutor_id,'Mock test topshirildi',t.title,t.offering_id);
  return public.oqi_mock_attempt_json(a);
end $$;

drop policy if exists oqi_group_messages_read on public.oqi_group_messages;
create policy oqi_group_messages_read on public.oqi_group_messages for select to authenticated using(public.oqi_classroom_access(offering_id));
grant select on public.oqi_group_messages to authenticated;
do $$ begin
  if exists(select 1 from pg_publication where pubname='supabase_realtime') and not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='oqi_group_messages') then
    alter publication supabase_realtime add table public.oqi_group_messages;
  end if;
end $$;

revoke all on function public.oqi_classroom_access(uuid),public.oqi_group_message_json(public.oqi_group_messages),public.oqi_mock_test_json(public.oqi_mock_tests),public.oqi_mock_attempt_json(public.oqi_mock_attempts),public.oqi_classroom_snapshot(),public.oqi_group_messages_read(uuid,uuid,integer),public.oqi_group_message_send(uuid,uuid,text,boolean),public.oqi_group_mark_read(uuid,timestamptz),public.oqi_mock_test_save(jsonb),public.oqi_mock_begin(uuid),public.oqi_mock_submit(uuid,jsonb) from public,anon,authenticated;
grant execute on function public.oqi_classroom_access(uuid),public.oqi_classroom_snapshot(),public.oqi_group_messages_read(uuid,uuid,integer),public.oqi_group_message_send(uuid,uuid,text,boolean),public.oqi_group_mark_read(uuid,timestamptz),public.oqi_mock_test_save(jsonb),public.oqi_mock_begin(uuid),public.oqi_mock_submit(uuid,jsonb) to authenticated;

-- Source: 202610260002_tutor_applications.sql
-- Tutor applications require a private phone number and a ready certificate.

create table if not exists public.oqi_tutor_applications (
  tutor_id uuid primary key references public.darsino_profiles(id) on delete cascade,
  contact_phone text not null check(contact_phone ~ '^\+[1-9][0-9]{8,14}$'),
  certificate_file_id uuid not null references public.darsino_files(id),
  submitted_at timestamptz not null default now()
);
alter table public.oqi_tutor_applications enable row level security;
revoke all on public.oqi_tutor_applications from public,anon,authenticated;

-- New accounts upload before their role/onboarded state is committed. This
-- permission alone does not create a tutor or put an incomplete draft in the queue.
do $upload$
declare definition text; previous text;
begin
  definition:=pg_get_functiondef('public.darsino_prepare_upload(text,text,text,bigint,text,uuid)'::regprocedure);
  previous:='exists(select 1 from public.darsino_tutors where user_id=me),''Repetitor profilini to‘ldiring.''';
  if position(previous in definition)>0 then
    execute replace(definition,previous,'(exists(select 1 from public.darsino_tutors where user_id=me) or exists(select 1 from public.darsino_profiles where id=me and not onboarded)),''Repetitor profilini to‘ldiring.''');
  elsif position('where id=me and not onboarded' in definition)=0 then
    raise exception 'Unexpected verification upload guard; application upgrade was not applied.';
  end if;
end $upload$;

do $$ begin
  if to_regprocedure('public.darsino_snapshot_tutor_base()') is null then
    alter function public.darsino_snapshot() rename to darsino_snapshot_tutor_base;
  end if;
  if to_regprocedure('public.darsino_mutate_tutor_base(jsonb)') is null then
    alter function public.darsino_mutate_idempotent_base(jsonb) rename to darsino_mutate_tutor_base;
  end if;
  if to_regprocedure('public.darsino_submit_document_tutor_base(uuid,text,text)') is null then
    alter function public.darsino_submit_document(uuid,text,text) rename to darsino_submit_document_tutor_base;
  end if;
end $$;

create or replace function public.darsino_snapshot() returns jsonb
language plpgsql security definer set search_path='' as $$
declare me uuid:=public.darsino_account_id(); result jsonb; market jsonb;
begin
  result:=public.darsino_snapshot_tutor_base(); market:=result->'market';
  market:=jsonb_set(market,'{tutorProfiles}',coalesce((select jsonb_agg(
    p.value || case when a.tutor_id is not null and (a.tutor_id=me or public.darsino_is_moderator()) then
      jsonb_build_object('contactPhone',a.contact_phone,'certificateFileId',a.certificate_file_id,'applicationSubmittedAt',a.submitted_at)
      else '{}'::jsonb end order by p.ordinality)
    from jsonb_array_elements(market->'tutorProfiles') with ordinality p(value,ordinality)
    left join public.oqi_tutor_applications a on a.tutor_id=(p.value->>'userId')::uuid),'[]'::jsonb));
  return result||jsonb_build_object('market',market);
end $$;

-- This is inside the existing public idempotency wrapper: a committed retry
-- returns its receipt without reopening an already reviewed application.
create or replace function public.darsino_mutate_idempotent_base(command jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare me uuid:=public.darsino_account_id(); actor public.darsino_profiles; payload jsonb;
  target uuid; file uuid; phone text; result jsonb; application boolean:=false;
begin
  if command->>'type' not in ('profile','tutor-profile','moderate') then
    return public.darsino_mutate_tutor_base(command);
  end if;
  if command->>'type' in ('profile','tutor-profile') then
    select * into actor from public.darsino_profiles where id=me for no key update;
  end if;
  if command->>'type'='tutor-profile' then
    perform public.darsino_assert(actor.role='tutor','Repetitor hisobiga kiring.');
    payload:=command->'profile'; application:=true;
  elsif command->>'type'='profile' and ((not actor.onboarded and coalesce(command->>'role',actor.role)='tutor') or (actor.role='tutor' and command->'tutor' is not null and command->'tutor'<>'null'::jsonb)) then
    payload:=command->'tutor'; application:=true;
  end if;
  if application then
    -- Existing content validation still runs; all writes roll back together.
    phone:=trim(coalesce(payload->>'contactPhone',''));
    perform public.darsino_assert(phone ~ '^\+[1-9][0-9]{8,14}$','Telefon raqamingizni xalqaro shaklda kiriting. Masalan, +998901234567.');
    file:=nullif(payload->>'certificateFileId','')::uuid;
    perform 1 from public.darsino_files f where f.id=file and f.owner_id=me and f.purpose='verification' and f.state='ready'
      and f.mime_type in ('application/pdf','image/jpeg','image/png','image/webp') and f.size_bytes between 1 and 10485760 for share;
    perform public.darsino_assert(found,'Sertifikatni PDF yoki rasm shaklida yuklang (10 MB gacha).');
    insert into public.oqi_tutor_applications(tutor_id,contact_phone,certificate_file_id)
      values(me,phone,file) on conflict(tutor_id) do update set contact_phone=excluded.contact_phone,certificate_file_id=excluded.certificate_file_id,submitted_at=now();
    if coalesce(char_length(trim(payload->>'proof')),0)<5 then payload:=jsonb_set(payload,'{proof}','"Yuklangan sertifikat"'); end if;
    -- Keep personal application fields out of the public tutor JSON forever.
    if command->>'type'='tutor-profile' then
      command:=jsonb_set(command,'{profile}',payload-'contactPhone'-'certificateFileId'-'applicationSubmittedAt');
    else
      command:=jsonb_set(command,'{tutor}',payload-'contactPhone'-'certificateFileId'-'applicationSubmittedAt');
    end if;
  elsif command->>'type'='moderate' then
    perform public.darsino_assert(public.darsino_is_moderator(),'Faqat moderator profilni tasdiqlaydi.');
    target:=(command->>'tutorId')::uuid;
    perform 1 from public.darsino_profiles where id=target for no key update;
    if command->>'decision'='approved' then
      perform public.darsino_assert(exists(select 1 from public.oqi_tutor_applications a join public.darsino_files f on f.id=a.certificate_file_id
        where a.tutor_id=target and f.owner_id=target and f.purpose='verification' and f.state='ready'
        and a.contact_phone ~ '^\+[1-9][0-9]{8,14}$'
        and exists(select 1 from public.darsino_tutor_documents d where d.tutor_id=target and d.file_id=f.id and d.status in ('pending','approved'))),
        'Avval o‘qituvchi telefon raqami va sertifikatini yuborsin.');
    end if;
  end if;
  result:=public.darsino_mutate_tutor_base(command);
  if application then
    insert into public.darsino_tutor_documents(tutor_id,file_id,document_type,label)
      values(me,file,'certificate','O‘qituvchi sertifikati') on conflict(file_id) do update
      set status='pending',reviewer_id=null,review_note='',reviewed_at=null;
    return public.darsino_snapshot()||jsonb_build_object('id',result->'id');
  end if;
  return result;
end $$;

-- Additional documents use the same private application and approval boundary.
create or replace function public.darsino_submit_document(p_file_id uuid,p_document_type text,p_label text) returns uuid
language plpgsql security definer set search_path='' as $$
declare me uuid:=public.darsino_account_id(); result uuid;
begin
  perform 1 from public.darsino_profiles where id=me for no key update;
  perform public.darsino_assert(exists(select 1 from public.oqi_tutor_applications where tutor_id=me),'Avval telefon raqami va sertifikat bilan profilingizni yuboring.');
  result:=public.darsino_submit_document_tutor_base(p_file_id,p_document_type,p_label);
  update public.oqi_tutor_applications set certificate_file_id=p_file_id,submitted_at=now() where tutor_id=me and certificate_file_id<>p_file_id;
  return result;
end $$;

revoke all on function public.darsino_snapshot_tutor_base(),public.darsino_mutate_tutor_base(jsonb),public.darsino_mutate_idempotent_base(jsonb),public.darsino_submit_document_tutor_base(uuid,text,text) from public,anon,authenticated;
revoke all on function public.darsino_snapshot(),public.darsino_submit_document(uuid,text,text) from public,anon;
grant execute on function public.darsino_snapshot(),public.darsino_submit_document(uuid,text,text) to authenticated;
notify pgrst,'reload schema';

-- Source: 202610290001_assignments.sql
-- Additive homework module. No existing users, lessons or objects are removed.

create table if not exists public.oqi_assignments (
  id uuid primary key, offering_id uuid not null references public.darsino_offerings(id),
  teacher_id uuid not null references public.darsino_profiles(id),
  title text not null check(char_length(title) between 3 and 150),
  description text not null default '' check(char_length(description)<=10000),
  subject text not null, due_at timestamptz not null,
  status text not null default 'draft' check(status in ('draft','published','archived')),
  recipient_ids uuid[] not null default '{}', file_ids uuid[] not null default '{}',
  revision integer not null default 1, published_at timestamptz,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index if not exists oqi_assignments_group_due on public.oqi_assignments(offering_id,status,due_at);
create table if not exists public.oqi_assignment_submissions (
  id uuid primary key, assignment_id uuid not null references public.oqi_assignments(id),
  student_id uuid not null references public.darsino_profiles(id), version integer not null,
  content text not null default '' check(char_length(content)<=10000), file_ids uuid[] not null default '{}',
  status text not null default 'submitted' check(status in ('submitted','accepted','changes_requested')),
  feedback text not null default '' check(char_length(feedback)<=5000),
  submitted_at timestamptz not null default now(), reviewed_at timestamptz,
  unique(assignment_id,student_id,version)
);
create index if not exists oqi_assignment_submissions_owner on public.oqi_assignment_submissions(student_id,submitted_at desc);
create table if not exists public.oqi_assignment_files (
  id uuid primary key default gen_random_uuid(), assignment_id uuid not null references public.oqi_assignments(id),
  owner_id uuid not null references public.darsino_profiles(id), scope text not null check(scope in ('task','answer')),
  name text not null, mime text not null, size_bytes bigint not null check(size_bytes between 1 and 10485760),
  object_path text not null unique, state text not null default 'pending' check(state in ('pending','ready','deleting','deleted')),
  created_at timestamptz not null default now()
);
create index if not exists oqi_assignment_files_owner on public.oqi_assignment_files(owner_id,created_at);
create table if not exists public.oqi_assignment_events (
  id uuid primary key default gen_random_uuid(), user_id uuid not null references public.darsino_profiles(id),
  event_key text not null, assignment_id uuid not null references public.oqi_assignments(id),
  title text not null, body text not null, read boolean not null default false,
  created_at timestamptz not null default now(), unique(user_id,event_key)
);
create index if not exists oqi_assignment_events_user on public.oqi_assignment_events(user_id,created_at desc);

create or replace function public.oqi_assignment_owner(p_group uuid) returns boolean
language sql stable security definer set search_path='' as $$
 select public.darsino_authenticated() and exists(select 1 from public.darsino_offerings o join public.darsino_tutors t on t.user_id=o.tutor_id where o.id=p_group and o.tutor_id=auth.uid() and t.verification='approved')
$$;
create or replace function public.oqi_assignment_access(p_id uuid) returns boolean
language sql stable security definer set search_path='' as $$
 select public.darsino_authenticated() and exists(select 1 from public.oqi_assignments a where a.id=p_id and public.oqi_classroom_access(a.offering_id) and
 (a.teacher_id=auth.uid() or (a.status<>'draft' and (cardinality(a.recipient_ids)=0 or auth.uid()=any(a.recipient_ids)))))
$$;
create or replace function public.oqi_assignment_file_access(p_id uuid) returns boolean
language sql stable security definer set search_path='' as $$
 select public.darsino_authenticated() and exists(select 1 from public.oqi_assignment_files f where f.id=p_id and f.state='ready' and
 (f.owner_id=auth.uid() or (public.oqi_assignment_access(f.assignment_id) and (
 exists(select 1 from public.oqi_assignments a where a.id=f.assignment_id and f.id=any(a.file_ids)) or
 exists(select 1 from public.oqi_assignment_submissions s join public.oqi_assignments a on a.id=s.assignment_id where s.assignment_id=f.assignment_id and f.id=any(s.file_ids) and auth.uid() in (s.student_id,a.teacher_id))))))
$$;

-- RLS reads are also safe if an API client bypasses the application RPCs.
alter table public.oqi_assignments enable row level security;
alter table public.oqi_assignment_submissions enable row level security;
alter table public.oqi_assignment_files enable row level security;
alter table public.oqi_assignment_events enable row level security;
revoke all on public.oqi_assignments,public.oqi_assignment_submissions,public.oqi_assignment_files,public.oqi_assignment_events from public,anon,authenticated;
grant select on public.oqi_assignments,public.oqi_assignment_submissions,public.oqi_assignment_files,public.oqi_assignment_events to authenticated;
drop policy if exists oqi_assignments_read on public.oqi_assignments;
create policy oqi_assignments_read on public.oqi_assignments for select to authenticated using(public.oqi_assignment_access(id));
drop policy if exists oqi_submissions_read on public.oqi_assignment_submissions;
create policy oqi_submissions_read on public.oqi_assignment_submissions for select to authenticated using(public.oqi_assignment_access(assignment_id) and (student_id=auth.uid() or exists(select 1 from public.oqi_assignments a where a.id=assignment_id and a.teacher_id=auth.uid())));
drop policy if exists oqi_assignment_files_read on public.oqi_assignment_files;
create policy oqi_assignment_files_read on public.oqi_assignment_files for select to authenticated using(public.oqi_assignment_file_access(id) or (public.darsino_authenticated() and owner_id=auth.uid() and state in ('pending','deleting')));
drop policy if exists oqi_assignment_events_read on public.oqi_assignment_events;
create policy oqi_assignment_events_read on public.oqi_assignment_events for select to authenticated using(public.darsino_authenticated() and user_id=auth.uid());

create or replace function public.oqi_assignments_snapshot() returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare me uuid:=public.darsino_account_id();
begin
 return jsonb_build_object(
 'assignments',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'offeringId',a.offering_id,'teacherId',a.teacher_id,'title',a.title,'description',a.description,'subject',a.subject,'dueAt',a.due_at,'status',a.status,'recipientIds',case when a.teacher_id=me then to_jsonb(a.recipient_ids) else '[]'::jsonb end,'fileIds',a.file_ids,'revision',a.revision,'publishedAt',a.published_at,'createdAt',a.created_at) order by a.due_at) from public.oqi_assignments a where public.oqi_assignment_access(a.id)),'[]'::jsonb),
 'submissions',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'assignmentId',s.assignment_id,'studentId',s.student_id,'version',s.version,'content',s.content,'fileIds',s.file_ids,'status',s.status,'feedback',s.feedback,'submittedAt',s.submitted_at,'reviewedAt',s.reviewed_at) order by s.version desc) from public.oqi_assignment_submissions s join public.oqi_assignments a on a.id=s.assignment_id where public.oqi_assignment_access(a.id) and me in (s.student_id,a.teacher_id)),'[]'::jsonb),
 'files',coalesce((select jsonb_agg(jsonb_build_object('id',f.id,'assignmentId',f.assignment_id,'ownerId',f.owner_id,'scope',f.scope,'name',f.name,'mime',f.mime,'sizeBytes',f.size_bytes,'objectPath',f.object_path,'state',f.state)) from public.oqi_assignment_files f where public.oqi_assignment_file_access(f.id) or (f.owner_id=me and f.state in ('pending','deleting'))),'[]'::jsonb),
 'events',coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'assignmentId',e.assignment_id,'title',e.title,'body',e.body,'read',e.read,'createdAt',e.created_at) order by e.created_at desc) from (select * from public.oqi_assignment_events where user_id=me order by created_at desc limit 100) e),'[]'::jsonb));
end $$;
create or replace function public.oqi_assignment_save(p_assignment jsonb) returns uuid
language plpgsql security definer set search_path='' as $$
declare me uuid:=public.darsino_account_id(); old public.oqi_assignments;
 target uuid:=(p_assignment->>'id')::uuid; grp uuid:=(p_assignment->>'offeringId')::uuid;
 recipients uuid[]:=array(select distinct value::uuid from jsonb_array_elements_text(coalesce(p_assignment->'recipientIds','[]')) order by value::uuid);
 files uuid[]:=array(select distinct value::uuid from jsonb_array_elements_text(coalesce(p_assignment->'fileIds','[]')) order by value::uuid);
 title_value text:=trim(p_assignment->>'title'); body text:=coalesce(p_assignment->>'description','');
 state text:=p_assignment->>'status'; due timestamptz:=(p_assignment->>'dueAt')::timestamptz;
 rev integer:=coalesce((p_assignment->>'revision')::integer,0);
begin
 perform public.darsino_assert(octet_length(p_assignment::text)<=20000 and target is not null and public.oqi_assignment_owner(grp),'O‘z guruhingiz va tasdiqlangan ustoz profili kerak.');
 perform public.darsino_assert(char_length(title_value) between 3 and 150 and char_length(body)<=10000 and state in ('draft','published') and due is not null and isfinite(due),'Vazifa nomi, muddat va tavsifni tekshiring.');
 perform public.darsino_assert(cardinality(recipients)<=100 and cardinality(files)<=5,'Ko‘pi bilan 100 o‘quvchi va 5 fayl tanlang.');
 perform public.darsino_assert(exists(select 1 from public.darsino_offerings where id=grp and data->>'subject'=p_assignment->>'subject'),'Guruh fanini tanlang.');
 perform public.darsino_assert(not exists(select 1 from unnest(recipients) r where not exists(select 1 from public.darsino_enrollments e where e.offering_id=grp and e.student_id=r and e.active)),'Faqat guruhingizdagi o‘quvchini tanlang.');
 perform pg_advisory_xact_lock(hashtextextended('oqi-assignment:'||target::text,0));
 select * into old from public.oqi_assignments where id=target for update;
 if found then
  perform public.darsino_assert(old.teacher_id=me and old.offering_id=grp,'Boshqa ustoz vazifasini o‘zgartirib bo‘lmaydi.');
  if (old.title,old.description,old.subject,old.due_at,old.status,old.recipient_ids,old.file_ids) is not distinct from (title_value,body,p_assignment->>'subject',due,state,recipients,files) then return target; end if;
  perform public.darsino_assert(old.status='draft' and old.revision=rev,'Vazifa o‘zgargan yoki allaqachon e’lon qilingan. Yangilang.');
 else
  perform public.darsino_assert(rev=0,'Vazifa topilmadi.');
 end if;
 perform 1 from public.oqi_assignment_files where id=any(files) order by id for update;
 perform public.darsino_assert(not exists(select 1 from unnest(files) f where not exists(select 1 from public.oqi_assignment_files x where x.id=f and x.owner_id=me and x.assignment_id=target and x.scope='task' and x.state='ready')),'Vazifaga tegishli tayyor fayllarni tanlang.');
 if state='published' then perform public.darsino_assert(due>now(),'Muddat kelajakda bo‘lsin.'); end if;
 perform public.darsino_account_rate('assignment-save',60,60);
 insert into public.oqi_assignments(id,offering_id,teacher_id,title,description,subject,due_at,status,recipient_ids,file_ids,published_at)
 values(target,grp,me,title_value,body,p_assignment->>'subject',due,state,recipients,files,case when state='published' then now() end)
 on conflict(id) do update set title=excluded.title,description=excluded.description,subject=excluded.subject,due_at=excluded.due_at,status=excluded.status,recipient_ids=excluded.recipient_ids,file_ids=excluded.file_ids,revision=oqi_assignments.revision+1,published_at=excluded.published_at,updated_at=now();
 if state='published' then
  insert into public.oqi_assignment_events(user_id,event_key,assignment_id,title,body)
  select e.student_id,'published:'||target,target,'Yangi uy vazifasi',title_value from public.darsino_enrollments e where e.offering_id=grp and e.active and (cardinality(recipients)=0 or e.student_id=any(recipients)) on conflict(user_id,event_key) do nothing;
 end if;
 return target;
end $$;
create or replace function public.oqi_assignment_submit(p_id uuid,p_assignment uuid,p_content text,p_files uuid[] default '{}') returns uuid
language plpgsql security definer set search_path='' as $$
declare me uuid:=public.darsino_account_id(); a public.oqi_assignments; prior public.oqi_assignment_submissions; latest public.oqi_assignment_submissions;
 content_value text:=trim(coalesce(p_content,'')); files uuid[]:=array(select distinct v from unnest(coalesce(p_files,'{}')) v order by v);
begin
 perform public.darsino_assert(public.oqi_assignment_access(p_assignment),'Bu vazifaga ruxsat yo‘q.');
 select * into a from public.oqi_assignments where id=p_assignment for update;
 perform public.darsino_assert(a.teacher_id<>me and exists(select 1 from public.darsino_profiles where id=me and role='student'),'Faqat o‘quvchi javob topshiradi.');
 perform public.darsino_assert(p_id is not null and char_length(content_value)<=10000 and (char_length(content_value)>0 or cardinality(files)>0) and cardinality(files)<=5,'Javob yozing yoki 5 tagacha fayl biriktiring.');
 perform pg_advisory_xact_lock(hashtextextended('oqi-submission:'||p_id::text,0));
 select * into prior from public.oqi_assignment_submissions where id=p_id;
 if found then
  perform public.darsino_assert(prior.student_id=me and prior.assignment_id=p_assignment and prior.content=content_value and prior.file_ids=files,'Javob kaliti boshqa amal uchun ishlatilgan.'); return p_id;
 end if;
 perform public.darsino_assert(a.status='published','Vazifa topshirish uchun ochiq emas.');
 perform 1 from public.oqi_assignment_files where id=any(files) order by id for update;
 perform public.darsino_assert(not exists(select 1 from unnest(files) f where not exists(select 1 from public.oqi_assignment_files x where x.id=f and x.owner_id=me and x.assignment_id=p_assignment and x.scope='answer' and x.state='ready')),'Faqat o‘z javob fayllaringizni biriktiring.');
 select * into latest from public.oqi_assignment_submissions where assignment_id=p_assignment and student_id=me order by version desc limit 1;
 perform public.darsino_assert(latest.id is null or latest.status='changes_requested','Javob tekshiruvda yoki qabul qilingan.');
 perform public.darsino_account_rate('assignment-submit',60,30);
 insert into public.oqi_assignment_submissions(id,assignment_id,student_id,version,content,file_ids) values(p_id,p_assignment,me,coalesce(latest.version,0)+1,content_value,files);
 insert into public.oqi_assignment_events(user_id,event_key,assignment_id,title,body) values(a.teacher_id,'submitted:'||p_id,p_assignment,'Uy vazifasi topshirildi',a.title) on conflict(user_id,event_key) do nothing;
 return p_id;
end $$;
create or replace function public.oqi_assignment_review(p_submission uuid,p_status text,p_feedback text) returns void
language plpgsql security definer set search_path='' as $$
declare me uuid:=public.darsino_account_id(); s public.oqi_assignment_submissions; a public.oqi_assignments; note text:=trim(coalesce(p_feedback,''));
begin
 select * into s from public.oqi_assignment_submissions where id=p_submission;
 select * into a from public.oqi_assignments where id=s.assignment_id for update;
 perform public.darsino_assert(a.teacher_id=me and public.oqi_assignment_owner(a.offering_id),'Faqat guruh ustozi javobni tekshiradi.');
 select * into s from public.oqi_assignment_submissions where id=p_submission for update;
 perform public.darsino_assert(p_status in ('accepted','changes_requested') and char_length(note)<=5000 and (p_status<>'changes_requested' or char_length(note)>0),'Qayta ishlash uchun izoh yozing.');
 if s.status=p_status and s.feedback=note then return; end if;
 perform public.darsino_assert(s.status='submitted','Bu javob allaqachon tekshirilgan.');
 update public.oqi_assignment_submissions set status=p_status,feedback=note,reviewed_at=now() where id=p_submission;
 insert into public.oqi_assignment_events(user_id,event_key,assignment_id,title,body) values(s.student_id,'reviewed:'||p_submission,a.id,case when p_status='accepted' then 'Vazifangiz qabul qilindi' else 'Vazifani qayta ishlang' end,a.title) on conflict(user_id,event_key) do nothing;
end $$;
create or replace function public.oqi_assignment_archive(p_assignment uuid) returns void
language plpgsql security definer set search_path='' as $$
begin
 perform public.darsino_assert(exists(select 1 from public.oqi_assignments a where a.id=p_assignment and public.oqi_assignment_owner(a.offering_id)),'Faqat o‘z vazifangizni yoping.');
 update public.oqi_assignments set status='archived',revision=revision+1,updated_at=now() where id=p_assignment and status<>'archived';
end $$;
create or replace function public.oqi_assignment_events_read() returns void
language plpgsql security definer set search_path='' as $$
declare me uuid:=public.darsino_account_id(); begin update public.oqi_assignment_events set read=true where user_id=me and not read; end $$;

-- A separate private bucket prevents assignment answers becoming public material.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('oqi-homework','oqi-homework',false,10485760,array['application/pdf','image/jpeg','image/png','image/webp'])
 on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create or replace function public.oqi_assignment_file_prepare(p_assignment uuid,p_scope text,p_name text,p_mime text,p_size bigint) returns jsonb
language plpgsql security definer set search_path='' as $$
declare me uuid:=public.darsino_account_id(); f public.oqi_assignment_files; target uuid:=gen_random_uuid(); a public.oqi_assignments;
begin
 select * into a from public.oqi_assignments where id=p_assignment;
 perform public.darsino_assert(public.oqi_assignment_access(p_assignment) and ((p_scope='task' and a.status='draft' and public.oqi_assignment_owner(a.offering_id)) or (p_scope='answer' and a.status='published' and a.teacher_id<>me and exists(select 1 from public.darsino_profiles where id=me and role='student'))),'Fayl yuklashga ruxsat yo‘q.');
 perform public.darsino_assert(p_mime in ('application/pdf','image/jpeg','image/png','image/webp') and p_size between 1 and 10485760 and char_length(p_name) between 1 and 160,'PDF yoki rasm, 10 MB gacha fayl tanlang.');
 perform 1 from public.darsino_profiles where id=me for no key update;
 perform public.darsino_assert((select count(*) from public.oqi_assignment_files where owner_id=me and created_at>now()-interval '1 hour')<40 and (select coalesce(sum(case when state in ('pending','deleting') then 10485760 else size_bytes end),0) from public.oqi_assignment_files where owner_id=me and state<>'deleted')+10485760<=104857600,'Uy vazifasi fayllari limiti tugadi.');
 insert into public.oqi_assignment_files(id,assignment_id,owner_id,scope,name,mime,size_bytes,object_path) values(target,p_assignment,me,p_scope,p_name,p_mime,p_size,me::text||'/'||target::text) returning * into f;
 return jsonb_build_object('id',f.id,'assignmentId',f.assignment_id,'ownerId',f.owner_id,'scope',f.scope,'name',f.name,'mime',f.mime,'sizeBytes',f.size_bytes,'objectPath',f.object_path,'state',f.state);
end $$;
create or replace function public.oqi_assignment_file_ready(p_file uuid) returns void
language plpgsql security definer set search_path='' as $$
declare me uuid:=public.darsino_account_id(); f public.oqi_assignment_files;
begin
 select * into f from public.oqi_assignment_files where id=p_file and owner_id=me for update;
 perform public.darsino_assert(found,'Fayl topilmadi.');
 perform public.darsino_assert(exists(select 1 from storage.objects o where o.bucket_id='oqi-homework' and o.name=f.object_path and o.owner_id=me::text and (o.metadata->>'size')::bigint=f.size_bytes and o.metadata->>'mimetype'=f.mime),'Fayl yuklanishi tugamagan.');
 update public.oqi_assignment_files set state='ready' where id=p_file;
end $$;
create or replace function public.oqi_homework_upload_allowed(p_path text) returns boolean
language sql stable security definer set search_path='' as $$
 select public.darsino_authenticated() and exists(select 1 from public.oqi_assignment_files f join public.oqi_assignments a on a.id=f.assignment_id where f.object_path=p_path and f.owner_id=auth.uid() and f.state='pending' and f.created_at>now()-interval '1 hour' and public.oqi_assignment_access(f.assignment_id) and ((f.scope='task' and a.status='draft') or (f.scope='answer' and a.status='published')))
$$;
drop policy if exists oqi_homework_upload on storage.objects;
create policy oqi_homework_upload on storage.objects for insert to authenticated with check(bucket_id='oqi-homework' and public.oqi_homework_upload_allowed(name));
drop policy if exists oqi_homework_download on storage.objects;
create policy oqi_homework_download on storage.objects for select to authenticated using(bucket_id='oqi-homework' and exists(select 1 from public.oqi_assignment_files f where f.object_path=storage.objects.name and (public.oqi_assignment_file_access(f.id) or (f.owner_id=auth.uid() and f.state='deleting'))));
create or replace function public.oqi_assignment_file_remove_begin(p_file uuid) returns text
language plpgsql security definer set search_path='' as $$
declare me uuid:=public.darsino_account_id(); f public.oqi_assignment_files;
begin
 select * into f from public.oqi_assignment_files where id=p_file and owner_id=me for update;
 perform public.darsino_assert(found,'Fayl topilmadi.');
 perform public.darsino_assert(not exists(select 1 from public.oqi_assignments a where p_file=any(a.file_ids)) and not exists(select 1 from public.oqi_assignment_submissions s where p_file=any(s.file_ids)),'Biriktirilgan yoki topshirilgan faylni o‘chirib bo‘lmaydi.');
 if f.state<>'deleted' then update public.oqi_assignment_files set state='deleting' where id=p_file; end if;
 return f.object_path;
end $$;
create or replace function public.oqi_assignment_file_remove_end(p_file uuid) returns void
language plpgsql security definer set search_path='' as $$
declare me uuid:=public.darsino_account_id(); f public.oqi_assignment_files;
begin
 select * into f from public.oqi_assignment_files where id=p_file and owner_id=me for update;
 perform public.darsino_assert(found and f.state in ('deleting','deleted'),'Avval faylni o‘chirishni boshlang.');
 perform public.darsino_assert(not exists(select 1 from storage.objects o where o.bucket_id='oqi-homework' and o.name=f.object_path),'Storage faylini avval o‘chiring.');
 update public.oqi_assignment_files set state='deleted' where id=p_file;
end $$;
create or replace function public.oqi_homework_remove_allowed(p_path text) returns boolean
language sql stable security definer set search_path='' as $$
 select public.darsino_authenticated() and exists(select 1 from public.oqi_assignment_files where object_path=p_path and owner_id=auth.uid() and state='deleting')
$$;
drop policy if exists oqi_homework_remove on storage.objects;
create policy oqi_homework_remove on storage.objects for delete to authenticated using(bucket_id='oqi-homework' and public.oqi_homework_remove_allowed(name));
-- No public bucket, overwrite policy or public signed URLs.
do $$ declare f record; begin
 for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('oqi_assignment_owner','oqi_assignment_access','oqi_assignment_file_access','oqi_assignments_snapshot','oqi_assignment_save','oqi_assignment_submit','oqi_assignment_review','oqi_assignment_archive','oqi_assignment_events_read','oqi_assignment_file_prepare','oqi_assignment_file_ready','oqi_homework_upload_allowed','oqi_assignment_file_remove_begin','oqi_assignment_file_remove_end','oqi_homework_remove_allowed') loop
 execute format('revoke all on function %s from public,anon',f.sig); execute format('grant execute on function %s to authenticated',f.sig);
 end loop;
end $$;

-- Source: 202610290002_student_privacy.sql
-- Safer defaults apply only to students completing onboarding after this upgrade.

create or replace function public.oqi_student_privacy_defaults() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 if new.onboarded and not old.onboarded and new.role='student' and auth.uid()=new.id and current_setting('role',true)='authenticated' then
  insert into public.darsino_account_settings(user_id,settings) values(new.id,'{"discoverable":false,"allowContactRequests":true,"showArea":false,"avatarVisibility":"contacts","messagePolicy":"contacts","invitePolicy":"contacts"}') on conflict(user_id) do nothing;
 end if;
 return new;
end $$;
revoke all on function public.oqi_student_privacy_defaults() from public,anon,authenticated;
drop trigger if exists oqi_student_privacy_defaults on public.darsino_profiles;
create trigger oqi_student_privacy_defaults after update of onboarded on public.darsino_profiles for each row execute function public.oqi_student_privacy_defaults();

-- Source: 202610290003_assignment_recipient_privacy.sql
-- Recipient lists belong to the teacher. Student RPC payloads already hide them;
-- column permissions close the same boundary for direct PostgREST queries.

revoke select on public.oqi_assignments from authenticated;
grant select(id,offering_id,teacher_id,title,description,subject,due_at,status,file_ids,revision,published_at,created_at,updated_at) on public.oqi_assignments to authenticated;

commit;
